INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q1', 'exam_primary_2023_arabic_jan', 1, 'فهم النص — المرادفات', '«بالنظر إلى الاهتمام الذي تلقته المدارس الذكية...»، مرادف كلمة "تلقته" في هذه الجملة هو:', false, '[{"id": "A", "text": "صادفته"}, {"id": "B", "text": "حظيت به"}, {"id": "C", "text": "توصلت به"}, {"id": "D", "text": "تسلّمته"}]'::jsonb, ARRAY['B']::text[], 'تلقّت الاهتمام بمعنى نالته وحظيت به.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q2', 'exam_primary_2023_arabic_jan', 2, 'فهم النص — مجال النص', 'يندرج هذا النص في مجال:', false, '[{"id": "A", "text": "الحياة الثقافية والفنية"}, {"id": "B", "text": "العلم والتكنولوجيا"}, {"id": "C", "text": "وسائل الاتصال والتواصل"}, {"id": "D", "text": "الابتكارات والاختراعات"}]'::jsonb, ARRAY['B']::text[], 'موضوع النص المدارس الذكية وتوظيف التكنولوجيا في التعليم، فهو من مجال العلم والتكنولوجيا.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q3', 'exam_primary_2023_arabic_jan', 3, 'فهم النص — القضية الأساس', 'القضية الأساس التي يطرحها النص هي:', false, '[{"id": "A", "text": "استعمال الإنترنت في عملية التعلم والتعليم"}, {"id": "B", "text": "أهمية التكنولوجيا في التعلم والتعليم"}, {"id": "C", "text": "إدماج تكنولوجيا المعلومات والاتصال في التعلم والتعليم"}, {"id": "D", "text": "عملية التعلم والتعليم في العصر الرقمي"}]'::jsonb, ARRAY['C']::text[], 'يدور النص حول دمج التقنيات الحديثة (تكنولوجيا المعلومات والاتصال) في التعليم والتعلم، مع مزاياه وعيوبه وشروطه.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, 'إجابة مرجّحة حسب المصدر (manasseb) — للتحقق');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q4', 'exam_primary_2023_arabic_jan', 4, 'جموع التكسير — صيغة منتهى الجموع', '«... أصبحت المدارس الذكية من أهم الأساليب ...»، كلمة "المدارس" في هذه الجملة:', false, '[{"id": "A", "text": "جمع قلة"}, {"id": "B", "text": "جمع كثرة"}, {"id": "C", "text": "صيغة منتهى الجموع"}, {"id": "D", "text": "جمع مؤنث سالم"}]'::jsonb, ARRAY['C']::text[], '«مدارس» على وزن «مفاعل»، وهي صيغة منتهى الجموع.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q5', 'exam_primary_2023_arabic_jan', 5, 'أنواع النصوص', 'النص عبارة عن:', false, '[{"id": "A", "text": "نص إخباري"}, {"id": "B", "text": "نص توجيهي"}, {"id": "C", "text": "نص وصفي"}, {"id": "D", "text": "نص حجاجي"}]'::jsonb, ARRAY['A']::text[], 'نص يقدم معلومات ومعطيات (تقرير اليونسكو، نسب مئوية) حول المدارس الذكية، فهو إخباري تفسيري.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, 'إجابة مرجّحة حسب المصدر (manasseb) — للتحقق');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q6', 'exam_primary_2023_arabic_jan', 6, 'فهم النص — الفقرة', 'الفقرة التي تتحدث عن مزايا المدرسة الذكية هي:', false, '[{"id": "A", "text": "الأولى"}, {"id": "B", "text": "الثانية"}, {"id": "C", "text": "الثالثة"}, {"id": "D", "text": "الرابعة"}]'::jsonb, ARRAY['B']::text[], 'الفقرة الثانية تعدد «الفوائد العديدة» لهذا النظام. والفقرة الأولى تعرّف المدرسة الذكية وتصف مكوناتها.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, 'إجابة مرجّحة حسب المصدر (manasseb) — للتحقق');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q7', 'exam_primary_2023_arabic_jan', 7, 'المصادر — مصدر الفعل الثلاثي', 'مصدر الفعل "حَسُنَ" في ما يأتي هو:', false, '[{"id": "A", "text": "تَحْسِين"}, {"id": "B", "text": "إِحْسَان"}, {"id": "C", "text": "تَحَسُّن"}, {"id": "D", "text": "حُسْن"}]'::jsonb, ARRAY['D']::text[], 'مصدر «حَسُنَ» الثلاثي هو «حُسْن». أما «تحسين» فمصدر «حسّن»، و«إحسان» مصدر «أحسن»، و«تحسّن» مصدر «تحسّن».', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q8', 'exam_primary_2023_arabic_jan', 8, 'الفعل المجرد والمزيد', '«... الذي أشار إلى أن هناك زيادة ملحوظة ...»، الفعل "أشار" في هذه الجملة:', false, '[{"id": "A", "text": "معتل مجرد"}, {"id": "B", "text": "صحيح مجرد"}, {"id": "C", "text": "معتل مزيد"}, {"id": "D", "text": "صحيح مزيد"}]'::jsonb, ARRAY['C']::text[], '«أشار» أصله «شَوَرَ»، فهو معتل أجوف، ومزيد بالهمزة على وزن «أفعل».', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q9', 'exam_primary_2023_arabic_jan', 9, 'المصادر — مصدر الفعل الخماسي', '«... وانقطاع التيار الكهربائي...»، كلمة "انقطاع" مصدر:', false, '[{"id": "A", "text": "ثلاثي مزيد"}, {"id": "B", "text": "رباعي مزيد"}, {"id": "C", "text": "ثلاثي مجرد"}, {"id": "D", "text": "رباعي مجرد"}]'::jsonb, ARRAY['A']::text[], '«انقطاع» مصدر «انقطع»، وهو ثلاثي (قطع) مزيد بحرفين.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q10', 'exam_primary_2023_arabic_jan', 10, 'الميزان الصرفي', 'الوزن الصرفي لكلمة "تميّز" في ما يأتي هو:', false, '[{"id": "A", "text": "تَفَعَّلَ"}, {"id": "B", "text": "تَفَعْلَلَ"}, {"id": "C", "text": "تَفَعُّل"}, {"id": "D", "text": "تَفَعِّل"}]'::jsonb, ARRAY['C']::text[], '«تميُّز» على وزن «تَفَعُّل».', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q11', 'exam_primary_2023_arabic_jan', 11, 'فهم النص — الفكرة الأساسية', 'الفكرة الأساسية للفقرة الأولى هي:', false, '[{"id": "A", "text": "شروط المدرسة الذكية"}, {"id": "B", "text": "مواصفات المدرسة الذكية"}, {"id": "C", "text": "أهداف المدرسة الذكية"}, {"id": "D", "text": "آفاق المدرسة الذكية"}]'::jsonb, ARRAY['B']::text[], 'الفقرة الأولى تعرّف المدرسة الذكية وتعدد تقنياتها ووسائلها، أي مواصفاتها.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q12', 'exam_primary_2023_arabic_jan', 12, 'التصغير', 'تصغير كلمة "مفتاح" في ما يأتي هو:', false, '[{"id": "A", "text": "مُفَيْتِيح"}, {"id": "B", "text": "مُفَيْتِح"}, {"id": "C", "text": "مُفَيْتَح"}, {"id": "D", "text": "مُفْتَاح"}]'::jsonb, ARRAY['A']::text[], 'تصغير «مفتاح»: «مُفَيْتِيح»، فتُقلب ألف ما قبل الآخر ياءً.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q13', 'exam_primary_2023_arabic_jan', 13, 'الإملاء — همزة ابن', 'الجملة التي كُتبت فيها كلمة "ابن" كتابة صحيحة هي:', false, '[{"id": "A", "text": "يا بن عليّ درستُ في مدرسة زيد بن محمد"}, {"id": "B", "text": "يا ابن عليّ درستُ في مدرسة زيد بن محمد"}, {"id": "C", "text": "يا ابن عليّ درستُ في مدرسة زيد ابن محمد"}, {"id": "D", "text": "يا بن عليّ درستُ في مدرسة زيد ابن محمد"}]'::jsonb, ARRAY['A']::text[], 'تُحذف همزة «ابن» بعد «يا» النداء، وإذا وقعت بين علمين ثانيهما أب للأول.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q14', 'exam_primary_2023_arabic_jan', 14, 'النداء — المنادى المضاف', 'الجملة الصحيحة في ما يأتي هي:', false, '[{"id": "A", "text": "يا مبدعي المدرسة الذكية، إنها امتداد للمدرسة الحالية"}, {"id": "B", "text": "يا مبدعين المدرسة الذكية، إنها امتداد للمدرسة الحالية"}, {"id": "C", "text": "يا مبدعو المدرسة الذكية، إنها امتداد للمدرسة الحالية"}, {"id": "D", "text": "يا مبدعون المدرسة الذكية، إنها امتداد للمدرسة الحالية"}]'::jsonb, ARRAY['A']::text[], '«مبدعي» منادى مضاف منصوب بالياء لأنه جمع مذكر سالم، وحُذفت النون للإضافة.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q15', 'exam_primary_2023_arabic_jan', 15, 'النسب', 'النسبة إلى كلمة "بيضاء" في ما يأتي هي:', false, '[{"id": "A", "text": "بَيْضَائِيّ"}, {"id": "B", "text": "بَيْضَاءِيّ"}, {"id": "C", "text": "بَيْضَاوِيّ"}, {"id": "D", "text": "بَيْضَوِيّ"}]'::jsonb, ARRAY['C']::text[], 'تُقلب همزة التأنيث الممدودة واوا في النسب: «بيضاويّ».', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, 'الاختياران A وB يختلفان فقط في رسم الهمزة (ئ مقابل ء) كما في المطبوع.');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q16', 'exam_primary_2023_arabic_jan', 16, 'الأساليب — التحذير', '«الإدمان، الإدمان على مواقع التواصل الاجتماعي.» هو أسلوب:', false, '[{"id": "A", "text": "مدح"}, {"id": "B", "text": "ذم"}, {"id": "C", "text": "إغراء"}, {"id": "D", "text": "تحذير"}]'::jsonb, ARRAY['D']::text[], 'تكرار الاسم منصوبا للتنبيه على أمر مكروه أسلوب تحذير.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q17', 'exam_primary_2023_arabic_jan', 17, 'إعراب الفعل المضارع — الأفعال الخمسة', '«... وأن 80% من المتعلمين ... يستخدمون ...»، تعرب "يستخدمون" في هذه الجملة فعلا مضارعا مرفوعا:', false, '[{"id": "A", "text": "بالواو، والفاعل ضمير مستتر تقديره هم، والجملة الفعلية في محل رفع خبر أن"}, {"id": "B", "text": "بثبوت النون، والواو ضمير في محل رفع فاعل، والجملة الفعلية في محل رفع خبر أن"}, {"id": "C", "text": "بالواو، والفاعل ضمير مستتر تقديره هم، والجملة الفعلية في محل نصب اسم أن"}, {"id": "D", "text": "بثبوت النون، والواو ضمير في محل رفع فاعل، والجملة الفعلية في محل نصب اسم أن"}]'::jsonb, ARRAY['B']::text[], 'فعل من الأفعال الخمسة يُرفع بثبوت النون، وواو الجماعة فاعل، والجملة خبر «أنّ».', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q18', 'exam_primary_2023_arabic_jan', 18, 'جموع التكسير — جمع عطشان', 'الجمع الصحيح لكلمة "عطشان" في ما يأتي هو:', false, '[{"id": "A", "text": "عَطْشَانُون"}, {"id": "B", "text": "عُطُش"}, {"id": "C", "text": "عَطَاشَى"}, {"id": "D", "text": "عِطَاش"}]'::jsonb, ARRAY['D']::text[], 'من جموع «عطشان»: «عَطاشى» و«عِطاش». ويحتمل أن يكون الاختيار C صحيحا أيضا حسب ضبطه في الأصل.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, 'إجابة مرجّحة حسب المصدر (manasseb) — للتحقق');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q19', 'exam_primary_2023_arabic_jan', 19, 'توكيد الفعل بالنون', 'يُؤكَّد الفعل "سعى" مع الضمير "أنتم" كالآتي:', false, '[{"id": "A", "text": "لَتَسْعَوُنَّ"}, {"id": "B", "text": "لَتَسْعَوْنَ"}, {"id": "C", "text": "لَتَسْعَوُنَّ"}, {"id": "D", "text": "لَتَسْعَوْنَّ"}]'::jsonb, ARRAY['C']::text[], '«لَتَسْعَوُنَّ»: تُحذف ألف الفعل وتبقى الفتحة قبل الواو، وتُضم الواو لالتقاء الساكنين مع نون التوكيد.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q20', 'exam_primary_2023_arabic_jan', 20, 'ما الموصولة', '«... ما جاء في تقرير ...»، "ما" في هذه الجملة:', false, '[{"id": "A", "text": "زائدة"}, {"id": "B", "text": "نافية"}, {"id": "C", "text": "تعجبية"}, {"id": "D", "text": "موصولة"}]'::jsonb, ARRAY['D']::text[], '«ما» اسم موصول بمعنى «الذي».', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q21', 'exam_primary_2023_arabic_jan', 21, 'إعراب الفعل المضارع — الضمة المقدرة', '«... وتقوي التواصل ...»، كلمة "تقوي" في هذه الجملة تعرب فعلا مضارعا مرفوعا بالضمة المقدرة على:', false, '[{"id": "A", "text": "ما قبل الياء منع من ظهورها التعذر، والفاعل ضمير مستتر تقديره هي"}, {"id": "B", "text": "الياء منع من ظهورها الاستثقال، والفاعل ضمير مستتر تقديره هي"}, {"id": "C", "text": "الياء منع من ظهورها التعذر، والفاعل ضمير مستتر تقديره هي"}, {"id": "D", "text": "ما قبل الياء منع من ظهورها الاستثقال، والفاعل ضمير مستتر تقديره هي"}]'::jsonb, ARRAY['B']::text[], 'الفعل المضارع المنتهي بالياء يُرفع بضمة مقدرة على الياء للثقل.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q22', 'exam_primary_2023_arabic_jan', 22, 'الأساليب — الاستغاثة', '«يا للأطفال بالإدمان على الهواتف النقالة.» هو أسلوب:', false, '[{"id": "A", "text": "نداء"}, {"id": "B", "text": "ندبة"}, {"id": "C", "text": "استغاثة"}, {"id": "D", "text": "تعجب"}]'::jsonb, ARRAY['C']::text[], '«يا» + «لَ» مفتوحة على المستغاث به + «لِ» مكسورة على المستغاث له: أسلوب استغاثة.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q23', 'exam_primary_2023_arabic_jan', 23, 'إعراب الفاعل — الضمة المقدرة', '«... الهائل الذي شهدته التكنولوجيا في العقود الأخيرة...»، تعرب كلمة "التكنولوجيا" في هذه الجملة:', false, '[{"id": "A", "text": "فاعلا مرفوعا بالضمة المقدرة على الألف، المانع من ظهورها التعذر"}, {"id": "B", "text": "مفعولا به منصوبا بالفتحة المقدرة على الألف، المانع من ظهورها الاستثقال"}, {"id": "C", "text": "فاعلا مرفوعا بالضمة المقدرة على الألف، المانع من ظهورها الاستثقال"}, {"id": "D", "text": "مفعولا به منصوبا بالفتحة المقدرة على الألف، المانع من ظهورها التعذر"}]'::jsonb, ARRAY['A']::text[], '«التكنولوجيا» فاعل «شهدته»، ورفعه بضمة مقدرة على الألف للتعذر.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q24', 'exam_primary_2023_arabic_jan', 24, 'الإملاء — الألف المتطرفة', 'الفعل المكتوب بطريقة صحيحة في ما يأتي هو:', false, '[{"id": "A", "text": "عَصَا الطفل والديه"}, {"id": "B", "text": "عَلَا الطفل فوق الربوة"}, {"id": "C", "text": "مَشَى الطفل بأفكاره البريئة"}, {"id": "D", "text": "خَلَى عمل الطفل من الشوائب"}]'::jsonb, ARRAY['B']::text[], '«علا» واوي (يعلو)، فيُكتب بألف قائمة. أما «عصى» فيائي (يعصي)، و«خلا» واوي (يخلو). والاختيار C «سعى» صحيح أيضا في رسمه، فيجب التحقق من الصورة الأصلية.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, 'إجابة مرجّحة حسب المصدر (manasseb) — للتحقق');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q25', 'exam_primary_2023_arabic_jan', 25, 'الاسم الجامد والمشتق', 'الاسم الجامد من بين الأسماء الآتية هو:', false, '[{"id": "A", "text": "الجهد"}, {"id": "B", "text": "الذكاء"}, {"id": "C", "text": "الابتكار"}, {"id": "D", "text": "التكنولوجيا"}]'::jsonb, ARRAY['D']::text[], '«التكنولوجيا» اسم معرّب لا يُشتق من فعل. ومع ذلك تُعد المصادر الأخرى جامدة في بعض التقسيمات.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, 'إجابة مرجّحة حسب المصدر (manasseb) — للتحقق');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q26', 'exam_primary_2023_arabic_jan', 26, 'بناء الفعل للمجهول', '«واجهت المدرسة الذكية تحديات نقدية»، تُبنى هذه الجملة للمجهول كما يأتي:', false, '[{"id": "A", "text": "وُوجِهَتْ تحدياتٌ نقديةٌ"}, {"id": "B", "text": "وُجِّهَتْ تحدياتٌ نقديةٌ"}, {"id": "C", "text": "وُاجِهَتْ تحدياتٌ نقديةٌ"}, {"id": "D", "text": "وُوجِّهَتْ تحدياتٌ نقديةٌ"}]'::jsonb, ARRAY['A']::text[], 'عند البناء للمجهول من «فاعَلَ» تُقلب الألف واوا: «ووجِهَت».', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q27', 'exam_primary_2023_arabic_jan', 27, 'العدد — كتابة الأعداد بالحروف', '«... ما جاء في تقرير التعليم العالمي لسنة 2020...»، العدد (2020) في هذه الجملة يُكتب بالحروف كالآتي:', false, '[{"id": "A", "text": "ألفين وعشرون"}, {"id": "B", "text": "ألفان وعشرون"}, {"id": "C", "text": "ألفين وعشرين"}, {"id": "D", "text": "ألفان وعشرين"}]'::jsonb, ARRAY['C']::text[], 'العدد مضاف إليه مجرور: «لسنة ألفين وعشرين».', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q28', 'exam_primary_2023_arabic_jan', 28, 'الإملاء — همزتا الوصل والقطع', 'الكلمة التي كُتبت بطريقة صحيحة في ما يأتي هي:', false, '[{"id": "A", "text": "الإصطناعي"}, {"id": "B", "text": "الابتكار"}, {"id": "C", "text": "الإفتراضي"}, {"id": "D", "text": "الإجتماعي"}]'::jsonb, ARRAY['B']::text[], 'همزة «الابتكار» همزة وصل لأنه مصدر الخماسي «ابتكر». وكذلك «الاصطناعي» و«الافتراضي» و«الاجتماعي» تُكتب بهمزة وصل.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q29', 'exam_primary_2023_arabic_jan', 29, 'المشتقات — الصفة المشبهة', '«... بطريقة سهلة وسريعة...»، كلمة "سهلة" في هذه الجملة:', false, '[{"id": "A", "text": "اسم فاعل"}, {"id": "B", "text": "صيغة مبالغة"}, {"id": "C", "text": "مصدر"}, {"id": "D", "text": "صفة مشبهة"}]'::jsonb, ARRAY['D']::text[], '«سهل» صفة مشبهة من فعل لازم دالة على الثبوت.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_arabic_jan_q30', 'exam_primary_2023_arabic_jan', 30, 'التمييز', '«... وأكثر تفاعلية وفعالية...»، كلمة "تفاعلية" في هذه الجملة:', false, '[{"id": "A", "text": "حال"}, {"id": "B", "text": "مفعول به"}, {"id": "C", "text": "تمييز"}, {"id": "D", "text": "نعت"}]'::jsonb, ARRAY['C']::text[], 'بعد اسم التفضيل «أكثر» يأتي اسم نكرة منصوب يزيل الإبهام، فهو تمييز.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41824-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q31', 'exam_primary_2023_french_jan', 31, 'Grammaire — nature du mot', 'À quelle catégorie grammaticale appartient le mot souligné dans la phrase suivante ? Pour devenir végétarien, il ne suffit pas de substituer les légumineuses aux protéines animales.', false, '[{"id": "A", "text": "Substantif"}, {"id": "B", "text": "Déterminant"}, {"id": "C", "text": "Adverbe"}, {"id": "D", "text": "Adjectif"}]'::jsonb, ARRAY['A']::text[], '« légumineuses » est précédé du déterminant « les » et désigne des plantes : c''est un nom.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q32', 'exam_primary_2023_french_jan', 32, 'Grammaire — fonction syntaxique', 'Quelle est la fonction syntaxique du mot souligné dans la phrase suivante ? Lequel de ces deux livres préfères-tu ?', false, '[{"id": "A", "text": "Sujet"}, {"id": "B", "text": "Complément de nom"}, {"id": "C", "text": "Complément d''objet indirect"}, {"id": "D", "text": "Complément d''objet direct"}]'::jsonb, ARRAY['D']::text[], '« Lequel » remplace l''objet de « préférer » (tu préfères ce livre) : COD.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q33', 'exam_primary_2023_french_jan', 33, 'Grammaire — forme impersonnelle', 'Laquelle des phrases suivantes est à la forme impersonnelle ?', false, '[{"id": "A", "text": "Il est grand maintenant, votre enfant !"}, {"id": "B", "text": "Il est content de nous raconter ses aventures."}, {"id": "C", "text": "Il est grand temps de passer à l''action."}, {"id": "D", "text": "Il a de la chance pour réussir."}]'::jsonb, ARRAY['C']::text[], '« Il » ne représente rien ; la tournure « il est temps de » est impersonnelle.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q34', 'exam_primary_2023_french_jan', 34, 'Grammaire — phrase complexe', 'Laquelle des phrases suivantes est une phrase complexe ?', false, '[{"id": "A", "text": "Au premier étage, il y avait d''abord la chambre de « Madame », très grande, tendue d''un papier à fleurs pâles, et contenant le portrait de « Monsieur »."}, {"id": "B", "text": "Je n''ai, dit-il, jamais rien vu de tel."}, {"id": "C", "text": "Le chasseur tout à fait perplexe, réfléchissait, visiblement combattu, tiré par le plaisir et une obligation, malheureux et troublé."}, {"id": "D", "text": "Bientôt les deux barques, poussées par les hommes, dévalent brusquement sur la pente de cailloux ronds, avec un bruit de toile."}]'::jsonb, ARRAY['B']::text[], 'Deux verbes conjugués (« ai vu » et l''incise « dit-il »), donc deux propositions. Les autres phrases n''ont qu''un verbe conjugué.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q35', 'exam_primary_2023_french_jan', 35, 'Grammaire — propositions', 'Combien y a-t-il de propositions dans la phrase suivante ? Mais les matelots se mettent à crier, battent leurs bordages avec les tolets de bois, et les oiseaux, pris de peur, s''élancent un à un, dans le vide, précipités jusqu''au ras de la vague. Guy De MAUPASSANT, La Roche aux Guillemots', false, '[{"id": "A", "text": "Deux propositions"}, {"id": "B", "text": "Trois propositions"}, {"id": "C", "text": "Quatre propositions"}, {"id": "D", "text": "Cinq propositions"}]'::jsonb, ARRAY['B']::text[], 'Trois verbes conjugués : « se mettent », « battent », « s''élancent ». Les participes ne forment pas de proposition.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q36', 'exam_primary_2023_french_jan', 36, 'Grammaire — subordonnée relative', 'Laquelle des phrases suivantes contient une proposition subordonnée relative ?', false, '[{"id": "A", "text": "Je souhaite qu''il réussisse."}, {"id": "B", "text": "Mon souhait est que mes enfants réussissent."}, {"id": "C", "text": "J''ai retrouvé la variété de café que je cherchais depuis quelques semaines."}, {"id": "D", "text": "Marche avec des sandales jusqu''à ce que la sagesse te procure des souliers."}]'::jsonb, ARRAY['C']::text[], '« que je cherchais » complète le nom « café » et est introduit par un pronom relatif.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q37', 'exam_primary_2023_french_jan', 37, 'Conjugaison — mode et temps', 'À quel mode et à quel temps est conjugué le verbe souligné dans la phrase suivante ? Il s''est caché de peur qu''elle ne le voie.', false, '[{"id": "A", "text": "Au présent de l''indicatif"}, {"id": "B", "text": "Au présent de l''impératif"}, {"id": "C", "text": "Au passé simple de l''indicatif"}, {"id": "D", "text": "Au présent du subjonctif"}]'::jsonb, ARRAY['D']::text[], '« de peur que » entraîne le subjonctif : « voie », présent du subjonctif.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q38', 'exam_primary_2023_french_jan', 38, 'Grammaire — subordonnée complétive', 'Laquelle des phrases suivantes contient une proposition subordonnée complétive ?', false, '[{"id": "A", "text": "Nous avouerons que notre héros était fort peu héros en ce moment."}, {"id": "B", "text": "Les vêtements que j''ai achetés sont les plus chers."}, {"id": "C", "text": "J''irai vous rejoindre après que vous aurez terminé votre travail."}, {"id": "D", "text": "Les histoires que nous avons lues sont très amusantes."}]'::jsonb, ARRAY['A']::text[], '« que notre héros était… » est COD du verbe « avouer » : subordonnée complétive. B et D sont des relatives, C une circonstancielle de temps.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q39', 'exam_primary_2023_french_jan', 39, 'Voix passive/active', 'Quelle est la transformation correcte, de la voix passive à la voix active, de la phrase suivante ? Un carpeau qui n''était encore que fretin fut pris par un pêcheur au bord d''une rivière.', false, '[{"id": "A", "text": "Un pêcheur au bord d''une rivière prend un carpeau qui n''était encore que fretin."}, {"id": "B", "text": "Un pêcheur au bord d''une rivière avait pris un carpeau qui n''était encore que fretin."}, {"id": "C", "text": "Un pêcheur au bord d''une rivière prit un carpeau qui n''était encore que fretin."}, {"id": "D", "text": "Un pêcheur au bord d''une rivière a pris un carpeau qui n''était encore que fretin."}]'::jsonb, ARRAY['C']::text[], '« fut pris » est un passé simple passif ; la forme active garde le même temps : « prit ».', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q40', 'exam_primary_2023_french_jan', 40, 'Lexicologie — formation des mots', 'Par quel procédé le mot « ophtalmologue » est-il formé ?', false, '[{"id": "A", "text": "Dérivation parasynthétique"}, {"id": "B", "text": "Préfixation"}, {"id": "C", "text": "Composition savante"}, {"id": "D", "text": "Suffixation"}]'::jsonb, ARRAY['C']::text[], 'Le mot associe deux éléments grecs, « ophtalmo- » (œil) et « -logue » : composition savante.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q41', 'exam_primary_2023_french_jan', 41, 'Orthographe — homophones', 'Lequel des mots ci-dessous convient pour compléter la phrase suivante ? Elle nous a préparé un ……………… qui n''est pas à dédaigner.', false, '[{"id": "A", "text": "met"}, {"id": "B", "text": "mets"}, {"id": "C", "text": "mais"}, {"id": "D", "text": "mes"}]'::jsonb, ARRAY['B']::text[], '« un mets » (plat) s''écrit avec un s même au singulier.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q42', 'exam_primary_2023_french_jan', 42, 'Phonétique — voyelles', 'Lequel des phonèmes, ci-dessous, correspond aux traits articulatoires suivants ? Voyelle orale ; postérieure ; arrondie ; fermée', false, '[{"id": "A", "text": "[u]"}, {"id": "B", "text": "[i]"}, {"id": "C", "text": "[y]"}, {"id": "D", "text": "[ø]"}]'::jsonb, ARRAY['A']::text[], '[u] est une voyelle orale, postérieure, arrondie et fermée. [i] est antérieure non arrondie, [y] antérieure arrondie, [ø] mi-fermée.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q43', 'exam_primary_2023_french_jan', 43, 'Phonétique — phonèmes vocaliques', 'Quelle est la liste exacte des phonèmes vocaliques du français ?', false, '[{"id": "A", "text": "/i/ - /e/ - /ɛ/ - /a/ - /ɑ/ - /y/ - /ø/ - /ɔ/ - /œ/ - /ɥ/ - /o/ - /ɑ̃/ - /ɛ̃/ - /ɔ̃/ - /œ̃/ - /ə/"}, {"id": "B", "text": "/i/ - /e/ - /ɛ/ - /a/ - /ɑ/ - /y/ - /ø/ - /w/ - /œ/ - /u/ - /o/ - /ɑ̃/ - /ɛ̃/ - /ɔ̃/ - /œ̃/ - /ə/"}, {"id": "C", "text": "/i/ - /e/ - /ɛ/ - /a/ - /ɑ/ - /j/ - /ø/ - /ɔ/ - /œ/ - /u/ - /o/ - /ɑ̃/ - /ɛ̃/ - /ɔ̃/ - /œ̃/ - /ə/"}, {"id": "D", "text": "/i/ - /e/ - /ɛ/ - /a/ - /ɑ/ - /y/ - /ø/ - /ɔ/ - /œ/ - /u/ - /o/ - /ɑ̃/ - /ɛ̃/ - /ɔ̃/ - /œ̃/ - /ə/"}]'::jsonb, ARRAY['D']::text[], 'Seule liste sans semi-voyelle ; A contient /ɥ/, B /w/ et C /j/.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, 'إجابة مرجّحة حسب المصدر (manasseb) — للتحقق : à confirmer sur un original lisible');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q44', 'exam_primary_2023_french_jan', 44, 'Phonétique — graphème « ch »', 'Lequel des mots suivants contient le graphème « ch » prononcée [k] ?', false, '[{"id": "A", "text": "Charade"}, {"id": "B", "text": "Orchidée"}, {"id": "C", "text": "Ranch"}, {"id": "D", "text": "Bronchite"}]'::jsonb, ARRAY['B']::text[], '« orchidée » se prononce [ɔʁkide] ; dans les autres mots, « ch » se prononce [ʃ].', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q45', 'exam_primary_2023_french_jan', 45, 'Phonétique — transcription phonétique', 'Quelle est la transcription phonétique correcte de la phrase suivante ? Mes clients sont les héros de mes histoires de marketing.', false, '[{"id": "A", "text": "[meklijɑ̃sɔ̃le eʁodəmezistwaʁdəmaʁketiŋ]"}, {"id": "B", "text": "[meklijɑ̃sɔ̃le zeʁodəmezistwaʁdəmaʁketiŋ]"}, {"id": "C", "text": "[meklijɑ̃sɔ̃le eʁodəmeistwaʁdəmaʁketiŋ]"}, {"id": "D", "text": "[meklijɔ̃sɑ̃le eʁodəmezistwaʁdəmaʁketiŋ]"}]'::jsonb, ARRAY['A']::text[], '« héros » commence par un h aspiré, donc pas de liaison : [le eʁo]. La liaison est obligatoire dans « mes histoires » [mezistwaʁ], et « sont » se transcrit [sɔ̃].', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, 'إجابة مرجّحة حسب المصدر (manasseb) — للتحقق : à confirmer sur un original lisible');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q46', 'exam_primary_2023_french_jan', 46, 'Types de textes — texte argumentatif', 'À quel type le texte suivant appartient-il ? Les activités humaines sont les principales sources de dégradation de la biodiversité. Pour survivre et pour avoir une condition de vie meilleure, l''homme a un besoin accru d''agrandir ses terres et d''utiliser les ressources biologiques. En d''autres mots, l''homme détruit l''environnement inconsciemment. On peut vraiment dire que la biodiversité est en danger. Mais pourquoi ? Quelles sont les principales causes ? En premier lieu, le changement climatique provient du fait que les activités humaines ont libéré des quantités colossales de gaz à effet de serre dans l''atmosphère, et ce, depuis le début de la révolution industrielle en 1750. En deuxième lieu, la surexploitation des écosystèmes : la surpêche, la chasse excessive d''animaux sauvages, l''abattage excessif de bois de chauffage et l''épuisement des terrains agricoles. Mais il arrivera un moment où l''écosystème ne sera plus en mesure de rétablir son équilibre naturel et certaines espèces deviendront de plus en plus rares ou disparaîtront. En dernier lieu, les effets négatifs de la pollution sur le fonctionnement des écosystèmes et la vie des espèces qui les composent, varient selon le milieu qu''elle contamine : les rivières et la raréfaction de certains poissons, les sols et la disparition des insectes utiles à leur formation et à leur stabilité. Alors, l''homme doit être conscient que ses actes peuvent nuire à son environnement, ce qui implique qu''il est très important de prendre des mesures dès maintenant pour préserver l''environnement et l''écosystème.', false, '[{"id": "A", "text": "Narratif"}, {"id": "B", "text": "Descriptif"}, {"id": "C", "text": "Argumentatif"}, {"id": "D", "text": "Injonctif"}]'::jsonb, ARRAY['C']::text[], 'Le texte avance une thèse (les activités humaines menacent la biodiversité), l''appuie par des arguments organisés (« en premier lieu… en dernier lieu ») et conclut par une recommandation. On peut aussi y voir un texte explicatif, mais ce choix n''est pas proposé.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q47', 'exam_primary_2023_french_jan', 47, 'Écrit fonctionnel — notice d''utilisation', 'Voici un écrit fonctionnel : - Versez de l''eau froide dans le réservoir de la cafetière. - Mettez du café moulu dans le filtre à café. - Branchez le cordon d''alimentation sur une prise de courant électrique. - Lorsque le témoin lumineux s''allume, appuyez sur le bouton « On ». - Quand il y a assez de café dans la verseuse, appuyez sur le bouton « Off ». Dans quel but cet écrit est-il utilisé ?', false, '[{"id": "A", "text": "Présenter une notice de fabrication"}, {"id": "B", "text": "Présenter une notice d''utilisation"}, {"id": "C", "text": "Présenter des consignes de sécurité"}, {"id": "D", "text": "Présenter des consignes d''évacuation"}]'::jsonb, ARRAY['B']::text[], 'Étapes de mise en marche d''une cafetière à l''impératif : notice d''utilisation.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q48', 'exam_primary_2023_french_jan', 48, 'Littérature — Balzac (registre)', 'Qu''évoquent les adjectifs énumérés dans l''extrait suivant ? Pour expliquer combien ce mobilier est vieux, crevassé, pourri, tremblant, rongé, manchot, borgne, invalide, expirant, il faudrait en faire une description qui retarderait trop l''intérêt de cette histoire [...] Honoré De BALZAC, Le père Goriot', false, '[{"id": "A", "text": "L''émerveillement du narrateur"}, {"id": "B", "text": "L''indifférence du narrateur"}, {"id": "C", "text": "Le dégoût du narrateur"}, {"id": "D", "text": "La satisfaction du narrateur"}]'::jsonb, ARRAY['C']::text[], 'L''accumulation d''adjectifs dépréciatifs (« pourri », « rongé », « expirant ») traduit le dégoût.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, 'La marge droite du scan coupe la fin de l''extrait (« manchot » et « Le père Goriot ») ; le texte a été complété d''après l''original (Balzac, Le père Goriot).');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q49', 'exam_primary_2023_french_jan', 49, 'Théâtre — Beaumarchais (aparté)', 'À qui Rosine s''adresse-t-elle dans l''extrait suivant ? LE COMTE chante : Réveillons-la, et s''avance vers Rosine. Qui de vous deux, mesdames, se nomme le docteur Balordo ? (À Rosine, bas.) Je suis Lindor. BARTHOLO. Bartholo ! ROSINE, à part. Il parle de Lindor. LE COMTE. Balordo, Barque-à-l''eau, je m''en moque comme de ça. Il s''agit seulement de savoir laquelle des deux... (À Rosine, lui montrant un papier.) Prenez cette lettre. Pierre-Augustin BEAUMARCHAIS, Le Barbier de Séville', false, '[{"id": "A", "text": "Au Comte"}, {"id": "B", "text": "À Bartholo"}, {"id": "C", "text": "À elle-même et au public"}, {"id": "D", "text": "Au Comte et à Bartholo"}]'::jsonb, ARRAY['C']::text[], 'L''indication « à part » signifie que le personnage parle pour lui-même, à l''intention du public.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, 'La marge droite du scan coupe quelques mots (« Je suis Lindor », « laquelle des deux… ») ; le texte a été complété d''après l''original (Beaumarchais, Le Barbier de Séville).');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q50', 'exam_primary_2023_french_jan', 50, 'Littérature — Corneille, Le Cid', 'Quelle est l''intention du personnage Don Diègue dans cette réplique ? Don Diègue — Sire, ainsi ces cheveux blanchis sous le harnois, Ce sang pour vous servir prodigué tant de fois, Ce bras, jadis l''effroi d''une armée ennemie, Descendaient au tombeau tout chargés d''infamie, Si je n''eusse produit un fils digne de moi, Digne de son pays et digne de son roi. Il m''a prêté sa main, il a tué le Comte ; Il m''a rendu l''honneur, il a lavé ma honte. Si montrer du courage et du ressentiment, Si venger un soufflet mérite un châtiment, Sur moi seul doit tomber l''éclat de la tempête : Quand le bras a failli, l''on en punit la tête. Pierre CORNEILLE, Le Cid', false, '[{"id": "A", "text": "Dénoncer un meurtre"}, {"id": "B", "text": "Décrire un meurtre"}, {"id": "C", "text": "Raconter un meurtre"}, {"id": "D", "text": "Justifier un meurtre"}]'::jsonb, ARRAY['D']::text[], 'Don Diègue défend Rodrigue : le meurtre du Comte était une réparation d''honneur, et il demande à être puni à sa place.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q51', 'exam_primary_2023_french_jan', 51, 'Conjugaison — valeur de l''imparfait', 'Quelle est la valeur de l''imparfait de l''indicatif dans la phrase suivante ? Ils marchaient depuis la première aube, sans s''arrêter, accélérant le pas, leur but étant d''arriver à temps.', false, '[{"id": "A", "text": "Une valeur durative"}, {"id": "B", "text": "Une valeur de potentialité"}, {"id": "C", "text": "Une valeur hypothétique"}, {"id": "D", "text": "Une valeur itérative"}]'::jsonb, ARRAY['A']::text[], 'Une action en cours qui dure (« depuis la première aube, sans s''arrêter ») : imparfait duratif.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q52', 'exam_primary_2023_french_jan', 52, 'Grammaire — connecteurs logiques', 'Quel type de lien le connecteur mis en gras marque-t-il dans l''extrait suivant ? Elle lui mit dans les mains un album, en le priant de le porter sur le piano. Mais il trouva moyen d''apprendre tout bas à Fauchery qu''on aurait Tatan Néné, la plus belle gorge de l''hiver, et Maria Blond, celle qui venait de débuter aux Folies-Dramatiques. Cependant, la Faloise l''arrêtait à chaque pas, attendant une invitation. [...] Émile ZOLA, Nana', false, '[{"id": "A", "text": "L''opposition"}, {"id": "B", "text": "La conséquence"}, {"id": "C", "text": "La cause"}, {"id": "D", "text": "L''explication"}]'::jsonb, ARRAY['A']::text[], '« Cependant » marque l''opposition ou la concession.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q53', 'exam_primary_2023_french_jan', 53, 'Compréhension — lecture', 'Le concierge entra dans le local des sciences de la nature. Une première surprise l''attendait. Une vaste flaque d''eau s''étalait sous les tables et des débris de verre jonchaient le sol. Il a dû placer toutes les chaises sur les bureaux tellement la surface à nettoyer était grande. Il ne comprenait pas ce qui s''était passé. Il se mit rapidement au boulot. Il fallait éviter que l''eau s''infiltre sous le plancher. Au moment où il finissait son travail, près du calorifère, une deuxième surprise : il trouva un petit poisson rouge. Il prit délicatement le poisson dans ses mains, éteignit la lumière et quitta la salle. Quelle était la cause de la première surprise pour le concierge ?', false, '[{"id": "A", "text": "Un miroir est tombé par terre et s''était brisé."}, {"id": "B", "text": "Le poisson rouge avait vidé son bol d''eau."}, {"id": "C", "text": "Le bol du poisson rouge s''était brisé."}, {"id": "D", "text": "Le concierge avait vidé une bouteille d''eau par terre."}]'::jsonb, ARRAY['C']::text[], 'Débris de verre, flaque d''eau, poisson rouge retrouvé par terre : son bocal s''était brisé.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q54', 'exam_primary_2023_french_jan', 54, 'Théâtre — Molière (comique)', 'De quel type de comique s''agit-il dans l''extrait suivant ? LE MAÎTRE D''ARMES — Vous êtes de plaisantes gens, de vouloir comparer vos sciences à la mienne. LE MAÎTRE DE MUSIQUE — Voyez un peu l''homme d''importance ! LE MAÎTRE À DANSER — Voilà un plaisant animal, avec son plastron ! LE MAÎTRE D''ARMES — Mon petit maître à danser, je vous ferais danser comme il faut. Et vous, mon petit musicien, je vous ferais chanter de la belle manière. LE MAÎTRE À DANSER — Monsieur le batteur de fer, je vous apprendrai votre métier. MONSIEUR JOURDAIN, au Maître à danser — Êtes-vous fou de l''aller quereller, lui qui entend la tierce et la quarte, et qui sait tuer un homme par raison démonstrative ? LE MAÎTRE À DANSER — Je me moque de sa raison démonstrative, et de sa tierce et de sa quarte. MONSIEUR JOURDAIN — Tout doux, vous dis-je. LE MAÎTRE D''ARMES — Comment ? Petit impertinent. MONSIEUR JOURDAIN — Eh ! Mon Maître d''armes. LE MAÎTRE À DANSER — Comment ? Grand cheval de carrosse. MONSIEUR JOURDAIN — Eh ! Mon Maître à danser. Molière, Le Bourgeois gentilhomme', false, '[{"id": "A", "text": "Comique de mœurs"}, {"id": "B", "text": "Comique de mots"}, {"id": "C", "text": "Comique de gestes"}, {"id": "D", "text": "Comique de situation"}]'::jsonb, ARRAY['B']::text[], 'Le comique naît des injures et des surnoms échangés (« plaisant animal », « batteur de fer », « grand cheval de carrosse ») : comique de mots. On peut aussi parler de comique de situation (la querelle).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, 'إجابة مرجّحة حسب المصدر (manasseb) — للتحقق : réponse probable ; une autre option peut être défendue selon la référence utilisée.');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q55', 'exam_primary_2023_french_jan', 55, 'Versification — décasyllabes', 'Quel est le type des vers suivants ? Ce toit tranquille, où marchent des colombes, Entre les pins palpite, entre les tombes ; Midi le juste y compose de feux La mer, la mer, toujours recommencée ! [...] Paul Valéry, Le cimetière marin', false, '[{"id": "A", "text": "Alexandrins"}, {"id": "B", "text": "Décasyllabes"}, {"id": "C", "text": "Octosyllabes"}, {"id": "D", "text": "Heptasyllabes"}]'::jsonb, ARRAY['B']::text[], 'Le Cimetière marin est écrit en décasyllabes : « Ce/ toit/ tran/quil/le, où/ mar/chent/ des/ co/lombes » = 10 syllabes.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q56', 'exam_primary_2023_french_jan', 56, 'Description — description parallèle', 'De quel type de description s''agit-il dans le texte suivant ? Le roi Louis X, comparé à son père, Felipe IV El Hermoso. Il est considéré par les historiens comme un mauvais souverain et un embarras pour la couronne française. Felipe était froid, peu bavard, implacable, mais juste. Un tyran pour certains, mais d''autres voyaient en lui un gestionnaire de l''ordre. Son fils Louis était également implacable. Mais il n''a pas recherché la justice, il a plutôt apprécié son pouvoir de transmettre sa cruauté. Avec chaque année de son court règne, il prouvait sa méchanceté. Certains à son époque le comparaient même au tyran romain Caligula.', false, '[{"id": "A", "text": "Description parallèle"}, {"id": "B", "text": "Description topographique"}, {"id": "C", "text": "Description portrait"}, {"id": "D", "text": "Description chronologique"}]'::jsonb, ARRAY['A']::text[], 'Le texte compare deux personnages, le père et le fils : description parallèle.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, 'La marge droite du scan coupe la fin de plusieurs lignes ; les mots ont été complétés d''après le contexte.');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q57', 'exam_primary_2023_french_jan', 57, 'Conte — structure du récit', 'Parmi les parties du conte, données en désordre et numérotées de 1 à 5 dans le tableau ci-dessous, laquelle en constitue la situation finale ? 1 On donna pour Marraines à la petite Princesse toutes les Fées qu''on pût trouver dans le pays. 2 Enfin pourtant l''Impératrice devint enceinte, et accoucha d''une fille. 3 Il était une fois, un Empereur et une Impératrice qui étaient si fâchés de n''avoir pas d''enfants, si fâchés qu''on ne saurait dire. 4 On fit un beau baptême. 5 Ils allèrent à toutes les eaux du monde ; vœux, pèlerinage, menues dévotions, tout fut mis en œuvre, et rien n''y faisait.', false, '[{"id": "A", "text": "1"}, {"id": "B", "text": "2"}, {"id": "C", "text": "4"}, {"id": "D", "text": "5"}]'::jsonb, ARRAY['A']::text[], 'Ordre du récit : 3 (situation initiale), 5, 2, 4, 1. La dernière partie est le choix des marraines (début de La Belle au bois dormant, Perrault).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q58', 'exam_primary_2023_french_jan', 58, 'Poésie — Verlaine (ordre des vers)', 'Parmi les propositions ci-dessous, quelle est celle où les vers de la strophe sont écrits dans le bon ordre ?', false, '[{"id": "A", "text": "Rien n''a changé. J''ai tout revu : l''humble tonnelle / Et le vieux tremble sa plainte sempiternelle. / Le jet d''eau fait toujours son murmure argentin / De vigne folle avec les chaises de rotin…"}, {"id": "B", "text": "Rien n''a changé. J''ai tout revu : l''humble tonnelle / De vigne folle avec les chaises de rotin… / Le jet d''eau fait toujours son murmure argentin / Et le vieux tremble sa plainte sempiternelle."}, {"id": "C", "text": "Le jet d''eau fait toujours son murmure argentin / Et le vieux tremble sa plainte sempiternelle. / Rien n''a changé. J''ai tout revu : l''humble tonnelle / De vigne folle avec les chaises de rotin…"}, {"id": "D", "text": "Rien n''a changé. J''ai tout revu : l''humble tonnelle / Le jet d''eau fait toujours son murmure argentin / Et le vieux tremble sa plainte sempiternelle. / De vigne folle avec les chaises de rotin…"}]'::jsonb, ARRAY['B']::text[], 'Rimes embrassées : tonnelle/rotin/argentin/sempiternelle ; la syntaxe impose « l''humble tonnelle / De vigne folle » (Verlaine, « Après trois ans »).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q59', 'exam_primary_2023_french_jan', 59, 'Connecteurs — texte à compléter', 'Voici un texte à compléter : Une bande de grenouilles décida d''organiser une course. L''enjeu était d''être la première à arriver tout en haut d''une tour très haute. .................... la nouvelle de la course se répandit dans le village, des tas de grenouilles curieuses se rassemblèrent pour voir et soutenir les concurrentes. Pleines de courage et de motivation, les candidates se placèrent sur la ligne de départ et commencèrent à grimper. Mais très vite, les grenouilles du public se mirent à faire des commentaires décourageants et négatifs : « Elles n''y arriveront jamais ! », « Elles sont bien trop lentes ! ». .................... quelques minutes, certaines grenouilles en course se sentirent démotivées et abandonnèrent. Celles qui persévérèrent finirent par succomber à la fatigue. .................... il ne restait que quelques grenouilles en lice, les commentaires des grenouilles spectatrices reprirent de plus belle : "Pour qui se prennent-elles, si c''était possible, nous l''aurions déjà fait !" dirent certaines. "On n''a jamais vu pareille sottise, les grenouilles ne sont pas faites pour grimper !" dirent d''autres. .................... du temps, les dernières concurrentes firent gagner par le découragement, toutes sauf une. Cette dernière grenouille grimpait lentement, sans relâche, .................... autour d''elle les commentaires se faisaient de plus en plus négatifs : « Descends, tu n''y arriveras jamais ! ». « Tu es ridicule ! ». Pourtant, la petite grenouille continua à avancer, lentement mais sûrement, sans faiblir. .................... un dernier effort, elle finit par gagner le sommet. Toutes les autres grenouilles se précipitèrent autour d''elle pour savoir comment elle avait fait pour réaliser ce que personne au monde n''avait encore jamais fait. L''une d''entre elles s''approcha pour lui demander sa recette. .................... elle découvrit que la petite championne était sourde. Dans quelle liste les mots sont-ils classés selon l''ordre qui convient pour compléter ce texte ?', false, '[{"id": "A", "text": "Dès que - Après - Alors qu'' - Au fil - tandis qu'' - Au bout de - C''est alors qu''"}, {"id": "B", "text": "Dès que - Au bout de - C''est alors qu'' - Au fil - tandis qu'' - Après - Alors qu''"}, {"id": "C", "text": "Dès que - Au bout de - Alors qu'' - Au fil - tandis qu'' - C''est alors qu'' - Après"}, {"id": "D", "text": "Dès que - Au bout de - Alors qu'' - Au fil - tandis qu'' - Après - C''est alors qu''"}]'::jsonb, ARRAY['D']::text[], 'Dès que la nouvelle… / Au bout de quelques minutes / Alors qu''il ne restait… / Au fil du temps / tandis qu''autour d''elle / Après un dernier effort / C''est alors qu''elle découvrit…', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_french_jan_q60', 'exam_primary_2023_french_jan', 60, 'Compréhension — ordre du texte', 'Voici ci-dessous les parties d''un texte, données en désordre et numérotées de 1 à 7 : 1 « Non, mais je fais ma part. », répétait le petit colibri aux autres animaux incrédules. 2 Seul le petit colibri s''activait, allant chercher quelques gouttes d''eau dans son bec pour les jeter sur le feu. 3 Un jour, il y eut un immense incendie de forêt. 4 « Colibri, tu es fou ! Tu crois que c''est avec ces gouttes d''eau que tu vas éteindre le feu ? » 5 Tous les animaux observaient le désastre, terrifiés et impuissants. 6 Au bout d''un moment, les autres animaux, agacés par ses agissements dérisoires, lui dirent : Pour reconstituer ce texte, quel est le bon ordre des parties ci-dessus ?', false, '[{"id": "A", "text": "3-2-5-6-4-1"}, {"id": "B", "text": "3-6-4-5-2-1"}, {"id": "C", "text": "3-5-2-6-4-1"}, {"id": "D", "text": "3-6-4-1-2-5"}]'::jsonb, ARRAY['C']::text[], '3 (l''incendie) → 5 (les animaux impuissants) → 2 (seul le colibri agit) → 6 et 4 (la remarque des animaux) → 1 (la réponse du colibri).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-41825-enseignant-2023/', true, 'L''option D est à peine lisible dans le scan (texte estompé).');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q61', 'exam_primary_2023_maths_jan', 61, 'Calcul — fractions', 'On pose : A = (1 − 1/3) / 3 × 3/4 − 1/5 ; On a :', false, '[{"id": "A", "text": "A = −1/5"}, {"id": "B", "text": "A = −1/30"}, {"id": "C", "text": "A = 13/10"}, {"id": "D", "text": "A = 1/20"}]'::jsonb, ARRAY['B']::text[], '(2/3)/3 = 2/9 ; 2/9 × 3/4 = 1/6 ; 1/6 − 1/5 = −1/30.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q62', 'exam_primary_2023_maths_jan', 62, 'Calcul — puissances', 'On pose : E = (2⁻¹ × 3³ × 10³) / (8⁻² × 5³ × 36) ; On a :', false, '[{"id": "A", "text": "E = 3/16"}, {"id": "B", "text": "E = 1/8"}, {"id": "C", "text": "E = 16"}, {"id": "D", "text": "E = 8"}]'::jsonb, ARRAY['C']::text[], 'Numérateur : 9×1000/8 = 1125 ; dénominateur : 125×36/64 = 4500/64 ; E = 1125×64/4500 = 16.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q63', 'exam_primary_2023_maths_jan', 63, 'Arithmétique — PPCM', 'Le plus petit multiple commun de 600 et 18 est :', false, '[{"id": "A", "text": "600"}, {"id": "B", "text": "2³×3²×5²"}, {"id": "C", "text": "600×18"}, {"id": "D", "text": "18"}]'::jsonb, ARRAY['B']::text[], '600 = 2³×3×5², 18 = 2×3² ; PPCM = 2³×3²×5² = 1800.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q64', 'exam_primary_2023_maths_jan', 64, 'Puissances de 10 — proportionnalité', 'Il y a environ 2,025×10¹³ globules rouges dans 4,5 litres de sang du corps humain. Combien de globules rouges y a-t-il dans trois litres de sang ?', false, '[{"id": "A", "text": "1,35×10¹³"}, {"id": "B", "text": "2,7×10¹³"}, {"id": "C", "text": "6,75×10¹³"}, {"id": "D", "text": "0,675×10¹³"}]'::jsonb, ARRAY['A']::text[], '2,025×10¹³ × 3/4,5 = 1,35×10¹³.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q65', 'exam_primary_2023_maths_jan', 65, 'Algèbre — nombres réels', 'Soient x et y deux nombres réels strictement positifs tels que : x > y et x² + y² = 3xy. On a : (x−y)/(x+y) =', false, '[{"id": "A", "text": "1/5"}, {"id": "B", "text": "−1"}, {"id": "C", "text": "√5"}, {"id": "D", "text": "√5/5"}]'::jsonb, ARRAY['D']::text[], '((x−y)/(x+y))² = (3xy−2xy)/(3xy+2xy) = 1/5 ; x>y donc le quotient est positif : 1/√5 = √5/5.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q66', 'exam_primary_2023_maths_jan', 66, 'Arithmétique — division euclidienne', 'Sachant que 3 est le reste de la division euclidienne de 2023 par 20, alors le reste de la division euclidienne de 2023⁵ par 20 est :', false, '[{"id": "A", "text": "3"}, {"id": "B", "text": "2"}, {"id": "C", "text": "1"}, {"id": "D", "text": "0"}]'::jsonb, ARRAY['A']::text[], '2023⁵ ≡ 3⁵ = 243 ≡ 3 (mod 20).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q67', 'exam_primary_2023_maths_jan', 67, 'Arithmétique — divisibilité', 'Le nombre 3⁶ − 2⁶ est divisible par :', false, '[{"id": "A", "text": "6"}, {"id": "B", "text": "19"}, {"id": "C", "text": "2"}, {"id": "D", "text": "3"}]'::jsonb, ARRAY['B']::text[], '729 − 64 = 665 = 5×7×19.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q68', 'exam_primary_2023_maths_jan', 68, 'Problème — équations', 'Ali a 180 Dh de plus que Badr. Si Ali donne 41 Dh à Badr, il aura deux fois plus d''argent que lui. Combien ont-ils chacun ?', false, '[{"id": "A", "text": "Ali a 200 Dh et Badr a 20 Dh"}, {"id": "B", "text": "Ali a 200 Dh et Badr a 59 Dh"}, {"id": "C", "text": "Ali a 239 Dh et Badr a 59 Dh"}, {"id": "D", "text": "Ali a 237 Dh et Badr a 57 Dh"}]'::jsonb, ARRAY['D']::text[], 'A = B + 180 et A − 41 = 2(B + 41) ⇒ B + 139 = 2B + 82 ⇒ B = 57, A = 237.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q69', 'exam_primary_2023_maths_jan', 69, 'Analyse — variations de la dérivée', 'On considère une fonction f définie et dérivable sur l''intervalle [−2 ; 3]. Le tableau ci-dessous représente les variations de la dérivée f′ de la fonction f (x : −2, −1, 0, 1, 3 ; f′(x) : 0, puis décroît jusqu''à −2, puis croît jusqu''à 0, puis croît jusqu''à 1, puis décroît jusqu''à 0).', false, '[{"id": "A", "text": "La fonction f est croissante sur l''intervalle [−1 ; 1]"}, {"id": "B", "text": "La fonction f est croissante sur [−2 ; 0] et décroissante sur [0 ; 3]"}, {"id": "C", "text": "La fonction f est décroissante sur [−2 ; 0] et croissante sur [0 ; 3]"}, {"id": "D", "text": "La fonction f est décroissante sur [0 ; 3]"}]'::jsonb, ARRAY['C']::text[], 'f'' ≤ 0 sur [−2 ; 0] (de 0 à −2 puis remonte à 0) et f'' ≥ 0 sur [0 ; 3].', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q70', 'exam_primary_2023_maths_jan', 70, 'Suites — suite arithmétique', 'Mariam a un salaire de 4000 Dh par mois. Sachant qu''elle recevra une augmentation mensuelle (chaque mois) de 75 Dh, quel sera le salaire de son onzième mois de travail ?', false, '[{"id": "A", "text": "44075 Dh"}, {"id": "B", "text": "44825 Dh"}, {"id": "C", "text": "4075 Dh"}, {"id": "D", "text": "4750 Dh"}]'::jsonb, ARRAY['D']::text[], 'Suite arithmétique : u₁₁ = 4000 + 10×75 = 4750 Dh.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q71', 'exam_primary_2023_maths_jan', 71, 'Pourcentages', 'Dans la période des soldes, le prix d''un téléphone portable est passé de 1200 Dh à 960 Dh, Quel est le pourcentage de cette réduction ?', false, '[{"id": "A", "text": "20%"}, {"id": "B", "text": "80%"}, {"id": "C", "text": "24%"}, {"id": "D", "text": "84%"}]'::jsonb, ARRAY['A']::text[], '(1200 − 960)/1200 = 240/1200 = 20 %.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q72', 'exam_primary_2023_maths_jan', 72, 'Arithmétique — décomposition en facteurs premiers', 'La décomposition en facteurs premiers du nombre 120 est :', false, '[{"id": "A", "text": "2²×3×10"}, {"id": "B", "text": "2²×6×5"}, {"id": "C", "text": "2³×3×5"}, {"id": "D", "text": "2×3×20"}]'::jsonb, ARRAY['C']::text[], '120 = 2³×3×5 (les autres contiennent des facteurs non premiers).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q73', 'exam_primary_2023_maths_jan', 73, 'Probabilités — dénombrement', 'Une urne contient huit boules portant les numéros 0, 0, 0, 0, 1, 1, 1, 2 (Toutes les boules sont indiscernables au toucher). On tire au hasard et simultanément deux boules de l''urne. Le nombre de tirages possibles pour que le produit des nombres portés par les deux boules tirées soit nul est :', false, '[{"id": "A", "text": "22"}, {"id": "B", "text": "6"}, {"id": "C", "text": "28"}, {"id": "D", "text": "12"}]'::jsonb, ARRAY['A']::text[], 'Total C(8,2) = 28 ; tirages sans 0 : C(4,2) = 6 ; 28 − 6 = 22.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q74', 'exam_primary_2023_maths_jan', 74, 'Géométrie analytique — droites perpendiculaires', 'Soit (D) la droite d''équation y = 2x − 1 et A(0 ; 3). L''équation réduite de la droite (Δ) qui passe par A et qui est perpendiculaire à (D) est :', false, '[{"id": "A", "text": "y = (1/2)x + 3"}, {"id": "B", "text": "y = −(1/2)x + 3"}, {"id": "C", "text": "y = 2x + 3"}, {"id": "D", "text": "y = −2x + 3"}]'::jsonb, ARRAY['B']::text[], 'Pente m'' = −1/2 (car 2×m'' = −1) et ordonnée à l''origine 3.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q75', 'exam_primary_2023_maths_jan', 75, 'Géométrie — angles (triangle rectangle)', 'OSM est un triangle rectangle en S (figure : angle en O = 67°, I est un point de [OM], le segment [SI] est tracé et SI ⟂ OM). La mesure de l''angle ISM est :', false, '[{"id": "A", "text": "67°"}, {"id": "B", "text": "23°"}, {"id": "C", "text": "45°"}, {"id": "D", "text": "70°"}]'::jsonb, ARRAY['A']::text[], 'La figure indique SI ⟂ OM : angle M = 90° − 67° = 23°, donc angle ISM = 90° − 23° = 67°.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q76', 'exam_primary_2023_maths_jan', 76, 'Géométrie — théorème de Thalès', 'Sachant que (AC) ∥ (BD), la valeur de x est : (figure : AC = 2, EC = 5, EB = x, BD = 1,2 ; E est le point d''intersection de [AD] et [BC])', false, '[{"id": "A", "text": "x = 3"}, {"id": "B", "text": "x = 1,5"}, {"id": "C", "text": "x = 5,8"}, {"id": "D", "text": "x = 4,2"}]'::jsonb, ARRAY['A']::text[], 'Thalès : EB/EC = BD/AC ⇒ x/5 = 1,2/2 ⇒ x = 3.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q77', 'exam_primary_2023_maths_jan', 77, 'Géométrie — trigonométrie (cercle)', 'Dans la figure ci-contre, (HG) est la tangente au cercle passant par le point G (figure : cercle de centre O et de rayon OG = 3 cm, angle GOH = 60°). La longueur du segment [OH] est :', false, '[{"id": "A", "text": "9 cm"}, {"id": "B", "text": "2√3 cm"}, {"id": "C", "text": "3√3 cm"}, {"id": "D", "text": "6 cm"}]'::jsonb, ARRAY['D']::text[], 'Triangle OGH rectangle en G : cos 60° = OG/OH ⇒ OH = 3/0,5 = 6 cm.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q78', 'exam_primary_2023_maths_jan', 78, 'Vecteurs — coordonnées', 'Dans le plan rapporté à un repère orthonormé, on considère les points A(1 ; 1), B(−1 ; 4), C(0 ; 2) et D(−2 ; 5) ; On a :', false, '[{"id": "A", "text": "AB⃗ = 2CD⃗"}, {"id": "B", "text": "AB⃗ = CD⃗"}, {"id": "C", "text": "AB⃗ = −(1/2)CD⃗"}, {"id": "D", "text": "AB⃗ = −2CD⃗"}]'::jsonb, ARRAY['B']::text[], 'AB(−2 ; 3) et CD(−2 ; 3).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q79', 'exam_primary_2023_maths_jan', 79, 'Géométrie dans l''espace — volume de la pyramide', 'Soit SABCD une pyramide de base carré ABCD et de hauteur (SA) tels que : AB = 4 cm et SA = 6 cm. Le volume de cette pyramide est :', false, '[{"id": "A", "text": "V = 96 cm³"}, {"id": "B", "text": "V = 144 cm³"}, {"id": "C", "text": "V = 32 cm³"}, {"id": "D", "text": "V = 24 cm³"}]'::jsonb, ARRAY['C']::text[], 'V = (1/3)×4²×6 = 32 cm³.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q80', 'exam_primary_2023_maths_jan', 80, 'Géométrie — triangle rectangle (Pythagore)', 'OAB est un triangle rectangle en O tel que : OA = a et OB = b ; Son hypoténuse a pour longueur 13 ; Son aire est égale à 30. Les longueurs a et b vérifient :', false, '[{"id": "A", "text": "a + b = 13 et ab = 30"}, {"id": "B", "text": "a + b = 17 et ab = 30"}, {"id": "C", "text": "a + b = 13 et ab = 60"}, {"id": "D", "text": "a + b = 17 et ab = 60"}]'::jsonb, ARRAY['D']::text[], 'ab/2 = 30 ⇒ ab = 60 ; (a+b)² = a² + b² + 2ab = 169 + 120 = 289 ⇒ a + b = 17.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q81', 'exam_primary_2023_maths_jan', 81, 'Vecteurs — relation de Chasles (figure)', 'Dans la figure ci-contre, on a : (figure : quadrillage ; à partir du point A, les vecteurs AB, AC et AG sont tracés)', false, '[{"id": "A", "text": "AG⃗ = 2AB⃗ + AC⃗"}, {"id": "B", "text": "AG⃗ = 2AB⃗ − AC⃗"}, {"id": "C", "text": "AG⃗ = AB⃗ + AC⃗"}, {"id": "D", "text": "AG⃗ = AB⃗ + 2AC⃗"}]'::jsonb, ARRAY['A']::text[], 'Sur le quadrillage : AB(3 ; 2), AC(5 ; −2), AG(11 ; 2) ; 2AB + AC = (6 + 5 ; 4 − 2) = (11 ; 2) = AG.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q82', 'exam_primary_2023_maths_jan', 82, 'Transformations — rotation', 'Quelle transformation partant de la figure (1) permet d''obtenir la figure (2) ? (figure : deux polygones (1) et (2) ayant un sommet commun)', false, '[{"id": "A", "text": "Une symétrie centrale"}, {"id": "B", "text": "Une rotation"}, {"id": "C", "text": "Une symétrie axiale"}, {"id": "D", "text": "Une translation"}]'::jsonb, ARRAY['B']::text[], 'Les deux figures ont un sommet commun fixe et la figure a tourné autour de ce point : rotation.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q83', 'exam_primary_2023_maths_jan', 83, 'Géométrie dans l''espace — pavé droit', 'ABCDEFGH est une boîte sous la forme d''un parallélépipède rectangle telle que : ABFE est un carré et AD = 25 cm. Nous remplissons un quart de la boîte avec un liquide. Sachant que le volume qu''occupe le liquide versé est 144 cm³, quelle est la longueur de l''arête [DC] ?', false, '[{"id": "A", "text": "DC = 2,4 cm"}, {"id": "B", "text": "DC = 23,04 cm"}, {"id": "C", "text": "DC = 4,8 cm"}, {"id": "D", "text": "DC = 6 cm"}]'::jsonb, ARRAY['C']::text[], 'AB = BF = c ; volume total = 4×144 = 576 = c²×25 ⇒ c² = 23,04 ⇒ c = 4,8 cm.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q84', 'exam_primary_2023_maths_jan', 84, 'Mesures — distances', 'Amine a fait une promenade en vélo en trois étapes de longueurs différentes : Étape 1 : 3 km 250 m ; Étape 2 : 3,4 km ; Étape 3 : 2850 m. Quelle est la distance totale parcourue par Amine ?', false, '[{"id": "A", "text": "6 km 440 m"}, {"id": "B", "text": "6 km 104 m"}, {"id": "C", "text": "9,5 km"}, {"id": "D", "text": "9 km 140 m"}]'::jsonb, ARRAY['C']::text[], '3250 + 3400 + 2850 = 9500 m = 9,5 km.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q85', 'exam_primary_2023_maths_jan', 85, 'Aires — partie colorée', 'Un carré de 60 cm de côté est divisé en neuf petits carrés identiques. Le grand carré contient trois cercles : - un cercle de rayon 10 cm (en bas à droite), - un cercle de rayon 8 cm (en haut à gauche), - un cercle de rayon 6 cm (en haut à droite), comme indiqué dans la figure ci-contre. L''aire de la partie colorée est :', false, '[{"id": "A", "text": "(2000 + 100π) cm²"}, {"id": "B", "text": "(2000 − 100π) cm²"}, {"id": "C", "text": "2400 cm²"}, {"id": "D", "text": "2000 cm²"}]'::jsonb, ARRAY['D']::text[], '5 petits carrés colorés de 400 cm² : 2000 cm². On retire le disque blanc de rayon 10 (100π) et on ajoute les deux petits disques colorés (64π + 36π = 100π) : 2000 − 100π + 100π = 2000 cm².', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, 'إجابة مرجّحة حسب المصدر (manasseb) — للتحقق : الصورة غير واضحة : الجواب يفترض أن الدائرتين الصغيرتين ملونتان والدائرة الكبيرة بيضاء.');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q86', 'exam_primary_2023_maths_jan', 86, 'Géométrie — périmètre du trapèze', 'Quel est le périmètre du trapèze ABED ? (figure : A et B en haut, D, C et E en bas ; BE = 8 cm, perpendiculaire à DE ; CE = 6 cm)', false, '[{"id": "A", "text": "54 cm"}, {"id": "B", "text": "44 cm"}, {"id": "C", "text": "114 cm"}, {"id": "D", "text": "124 cm"}]'::jsonb, ARRAY['B']::text[], 'BC = √(8² + 6²) = 10 cm. Si ABCD est un losange (AB = BC = AD = 10), ED = 10 + 6 = 16 et P = AB + BE + ED + DA = 10 + 8 + 16 + 10 = 44 cm.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, 'إجابة مرجّحة حسب المصدر (manasseb) — للتحقق : النص لا يعطي طول AB : الجواب يفترض أن ABCD معين، و44 هو الاقتراح الوحيد المطابق.');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q87', 'exam_primary_2023_maths_jan', 87, 'Géométrie dans l''espace — patron du prisme', 'La figure ci-contre représente le patron d''un prisme droit dont l''aire totale est égale à 148 cm² (figure : patron en croix ; largeur 6 cm, hauteur 4 cm). Quelle est en cm la longueur du côté [AB] ?', false, '[{"id": "A", "text": "AB = 10 cm"}, {"id": "B", "text": "AB = 6 cm"}, {"id": "C", "text": "AB = 4 cm"}, {"id": "D", "text": "AB = 5 cm"}]'::jsonb, ARRAY['D']::text[], 'Pavé 6 × AB × 4 : 2(6·AB + 6·4 + 4·AB) = 20·AB + 48 = 148 ⇒ AB = 5 cm.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q88', 'exam_primary_2023_maths_jan', 88, 'Statistiques — classe médiane', 'Une société en informatique fait une étude sur la durée de connexion via un ordinateur. Pour cela elle réalise une enquête auprès d''un échantillon de 200 clients et obtient les résultats suivants : Temps de connexion en heures par an : [200;400[ : 15 ; [400;600[ : 32 ; [600;800[ : 35 ; [800;1000[ : 78 ; [1000;1200[ : 31 ; [1200;1400[ : 9. La classe médiane de cette série statistique est :', false, '[{"id": "A", "text": "[800;1000["}, {"id": "B", "text": "[600;800["}, {"id": "C", "text": "[400;600["}, {"id": "D", "text": "[1000;1200["}]'::jsonb, ARRAY['A']::text[], 'Effectifs cumulés : 15, 47, 82, 160 ; la 100e valeur est dans [800 ; 1000[.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q89', 'exam_primary_2023_maths_jan', 89, 'Statistiques — moyenne', 'Le tableau suivant fournit les notes des élèves d''une classe lors d''un devoir de mathématiques : Notes : 2 (effectif 1), 4 (2), 5 (3), 7 (2), 8 (3), 9 (4), 10 (5). La moyenne des notes obtenues est :', false, '[{"id": "A", "text": "M = 5"}, {"id": "B", "text": "M = 8"}, {"id": "C", "text": "M = 7,45"}, {"id": "D", "text": "M = 7"}]'::jsonb, ARRAY['C']::text[], 'Σ = 2 + 8 + 15 + 14 + 24 + 36 + 50 = 149 ; N = 20 ; M = 7,45.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_maths_jan_q90', 'exam_primary_2023_maths_jan', 90, 'Statistiques — lecture graphique', 'Le graphe suivant représente les notes des élèves d''une classe lors d''un devoir de mathématiques (effectifs : note 2 → 1, note 4 → 2, note 5 → 3, note 7 → 2, note 8 → 3, note 9 → 4, note 10 → 5). Quel est le nombre d''élèves qui ont obtenu au plus la note 5 ?', false, '[{"id": "A", "text": "12"}, {"id": "B", "text": "3"}, {"id": "C", "text": "14"}, {"id": "D", "text": "6"}]'::jsonb, ARRAY['D']::text[], 'Notes 2, 4 et 5 : 1 + 2 + 3 = 6 élèves.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42525-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q91', 'exam_primary_2023_sciences_jan', 91, 'Biologie — lipides', 'Les lipides sont des molécules essentielles chez les êtres vivants, ils comprennent :', false, '[{"id": "A", "text": "les graisses, les cires, les glucides, les vitamines liposolubles, les glycérides et les phospholipides."}, {"id": "B", "text": "les graisses, les cires, les stérols, les protéines, les glycérides et les phospholipides."}, {"id": "C", "text": "les graisses, les cires, les stérols, les vitamines liposolubles, les acides nucléiques et les phospholipides."}, {"id": "D", "text": "les graisses, les cires, les stérols, les vitamines liposolubles, les glycérides et les phospholipides."}]'::jsonb, ARRAY['D']::text[], 'Glucides, protéines et acides nucléiques ne sont pas des lipides.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q92', 'exam_primary_2023_sciences_jan', 92, 'Biologie — acides nucléiques', 'Les différents types d''acides nucléiques jouent des rôles importants chez les êtres vivants car :', false, '[{"id": "A", "text": "Ils constituent des éléments structuraux des protéines."}, {"id": "B", "text": "Ils constituent des éléments structuraux des glucides."}, {"id": "C", "text": "Ils servent de support pour l''information génétique qui s''exprime par la synthèse des glucides."}, {"id": "D", "text": "Ils servent de support pour l''information génétique qui s''exprime par la synthèse des protéines."}]'::jsonb, ARRAY['D']::text[], 'ADN/ARN portent l''information génétique exprimée par la synthèse des protéines.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q93', 'exam_primary_2023_sciences_jan', 93, 'Biologie — cellule', 'La cellule animale et la cellule végétale ont en commun :', false, '[{"id": "A", "text": "1- un noyau ; 2- une membrane plasmique ; 3- un centrosome ; 4- un cytoplasme."}, {"id": "B", "text": "1- un cytoplasme ; 2- un noyau ; 3- des chloroplastes ; 4- une membrane plasmique."}, {"id": "C", "text": "1- un cytoplasme ; 2- un noyau ; 3- des mitochondries ; 4- une membrane plasmique."}, {"id": "D", "text": "1- un noyau ; 2- une membrane plasmique ; 3- une paroi squelettique ; 4- cytoplasme."}]'::jsonb, ARRAY['C']::text[], 'Centrosome (animale), chloroplastes et paroi (végétale) ne sont pas communs.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q94', 'exam_primary_2023_sciences_jan', 94, 'Biologie — respiration (grenouille)', 'La grenouille, passe par des étapes au cours de son cycle de vie, durant lesquelles elle respire grâce aux :', false, '[{"id": "A", "text": "branchies, poumons et trachées."}, {"id": "B", "text": "branchies, poumons et peau."}, {"id": "C", "text": "branchies et trachées."}, {"id": "D", "text": "trachées, poumons et peau."}]'::jsonb, ARRAY['B']::text[], 'Têtard : branchies ; adulte : poumons et respiration cutanée.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q95', 'exam_primary_2023_sciences_jan', 95, 'Biologie — reproduction des plantes (figure)', 'Les éléments qui correspondent à la légende sont : (Document 1 : schéma de la fleur et de la germination — labels 1 à 7)', false, '[{"id": "A", "text": "1- ovule; 2- anthère ; 3- filament; 4- stigmate ; 5- étamine ; 6-grain de pollen ; 7- germination."}, {"id": "B", "text": "1- grain de pollen ; 2- anthère ; 3- filament; 4- stigmate ; 5- étamine ; 6- ovule ; 7- germination."}, {"id": "C", "text": "1- grain de pollen ; 2- anthère ; 3- filament; 4- étamine ; 5- stigmate ; 6- ovule ; 7- germination."}, {"id": "D", "text": "1- ovule; 2- grain de pollen ; 3- filament; 4- étamine ; 5- stigmate ; 6- anthère ; 7- germination."}]'::jsonb, ARRAY['C']::text[], '(4) regroupe anthère (2) et filet (3) : c''est l''étamine ; (5) stigmate ; (6) ovule ; (1) grain de pollen ; (7) germination.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q96', 'exam_primary_2023_sciences_jan', 96, 'Biologie — fruit', 'Le fruit est un organe qui :', false, '[{"id": "A", "text": "se forme suite au développement de la graine."}, {"id": "B", "text": "contient une quantité variable de graines."}, {"id": "C", "text": "contient une quantité variable d''ovules."}, {"id": "D", "text": "se forme suite au développement de l''ovule."}]'::jsonb, ARRAY['B']::text[], 'Le fruit contient les graines, en quantité variable selon l''espèce ; il se forme à partir de l''ovaire, non de l''ovule (qui donne la graine).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q97', 'exam_primary_2023_sciences_jan', 97, 'Biologie — fleur (périanthe)', 'Le périanthe est:', false, '[{"id": "A", "text": "l''ensemble des organes femelles d''une fleur."}, {"id": "B", "text": "l''ensemble des enveloppes florales."}, {"id": "C", "text": "l''ensemble des organes mâles d''une fleur."}, {"id": "D", "text": "l''ensemble des organes mâles et femelles d''une fleur."}]'::jsonb, ARRAY['B']::text[], 'Périanthe = calice + corolle (enveloppes florales).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q98', 'exam_primary_2023_sciences_jan', 98, 'Biologie — appareil reproducteur (figure)', 'Les éléments qui correspondent à la légende sont : (Document 2 : schéma de l''appareil reproducteur chez l''homme — labels 1 à 8)', false, '[{"id": "A", "text": "1- urètre ; 2- canal déférent ; 3- pénis ; 4- scrotum ; 5- vésicule séminale ; 6- prostate ; 7- épididyme ; 8- testicule."}, {"id": "B", "text": "1- canal déférent ; 2- urètre ; 3- pénis ; 4- scrotum ; 5- prostate ; 6- vésicule séminale ; 7- épididyme ; 8- testicule."}, {"id": "C", "text": "1- urètre ; 2- canal déférent ; 3- pénis ; 4- scrotum ; 5- prostate ; 6- vésicule séminale ; 7- épididyme ; 8- testicule."}, {"id": "D", "text": "1- canal déférent ; 2- urètre ; 3- pénis ; 4- scrotum ; 5- vésicule séminale ; 6- prostate ; 7- épididyme ; 8- testicule."}]'::jsonb, ARRAY['D']::text[], 'Sur le document 2 : 1 canal déférent (il part du testicule et passe au-dessus de la vessie), 2 urètre, 3 pénis, 4 scrotum, 5 vésicule séminale, 6 prostate, 7 épididyme, 8 testicule.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q99', 'exam_primary_2023_sciences_jan', 99, 'Géologie — carte topographique', 'Les données suivantes correspondent aux éléments de la carte topographique ci-dessus : (Document 3 : carte topographique — courbes de niveau, points S1, S2, L1, L2)', false, '[{"id": "A", "text": "l''équidistance est 150m ; l''altitude des courbes de niveaux L1 : 2200m et L2 : 4600m ; l''altitude des points côtés S1 : 4751m et S2 : 4651m."}, {"id": "B", "text": "l''équidistance est 100m ; l''altitude des courbes de niveaux L1 : 2200m et L2 : 4200m ; l''altitude des points côtés S1 : 4651m et S2 : 4751m."}, {"id": "C", "text": "l''équidistance est 100m ; l''altitude des courbes de niveaux L1 : 2200m et L2 : 4200m ; l''altitude des points côtés S1 : 4751m et S2 : 4651m."}, {"id": "D", "text": "l''équidistance est 150m ; l''altitude des courbes de niveaux L1 : 2200m et L2 : 4200m ; l''altitude des points côtés S1 : 4651m et S2 : 4751m."}]'::jsonb, ARRAY['C']::text[], 'Entre les courbes maîtresses 2200 et 2700 (500 m), l''équidistance est de 100 m. S1 est entouré de plus de courbes fermées que S2 : c''est le point le plus haut (S1 = 4751 m, S2 = 4651 m).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, 'إجابة مرجّحة حسب المصدر (manasseb) — للتحقق : الخريطة غير واضحة في الصورة : الجواب مبني على عدد المنحنيات حول S1 وS2 ؛ تأكد منه على نسخة واضحة.');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q100', 'exam_primary_2023_sciences_jan', 100, 'Géologie — ondes sismiques', 'Les ondes sismiques ont les caractéristiques suivantes : (Document 4 : modèles de propagation des ondes L, S et P)', false, '[{"id": "A", "text": "les ondes L se propage en créant successivement des zones de dilatation et des zones de compression."}, {"id": "B", "text": "les ondes P se propage en créant successivement des zones de dilatation et des zones de compression."}, {"id": "C", "text": "les ondes L se propagent en créant une oscillation des particules dans un plan vertical, à angle droit par rapport au sens de propagation de l''onde."}, {"id": "D", "text": "les ondes S se propagent déplaçant le sol d''un côté à l''autre dans un plan horizontal perpendiculairement à sa direction de propagation sans mouvement vertical."}]'::jsonb, ARRAY['B']::text[], 'Les ondes P sont des ondes de compression-dilatation ; la proposition D décrit en fait les ondes de Love.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q101', 'exam_primary_2023_sciences_jan', 101, 'Géologie — ondes sismiques', 'Les ondes sismiques générées lors d''un séisme sont:', false, '[{"id": "A", "text": "les ondes P qui se propagent en surface et les ondes S et L qui se propagent en profondeur du globe terrestre."}, {"id": "B", "text": "les ondes P, S et L qui se propagent en surface du globe terrestre."}, {"id": "C", "text": "les ondes P et S qui se propagent en profondeur et les ondes L qui se propagent en surface du globe terrestre."}, {"id": "D", "text": "les ondes P, L et S qui se propagent en profondeur du globe terrestre."}]'::jsonb, ARRAY['C']::text[], 'P et S sont des ondes de volume ; L (Love) sont des ondes de surface.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, 'La marge droite du scan coupe la fin des options A et C (« du globe terrestre ») ; complété d''après le contexte.');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q102', 'exam_primary_2023_sciences_jan', 102, 'Géologie — discontinuités', 'Le comportement des ondes sismiques en profondeur de la Terre met en évidence la présence de discontinuités : (Document 5 : vitesse des ondes P et S en fonction de la profondeur — Manteau, Noyau)', false, '[{"id": "A", "text": "la discontinuité de Gutenberg définit la limite située entre le noyau terrestre et le manteau, et marque un contraste important de densité entre les deux."}, {"id": "B", "text": "la discontinuité de Mohorovicic (MOHO) définit la limite située entre le noyau terrestre et le manteau, et marque un contraste de densité entre les deux."}, {"id": "C", "text": "la discontinuité de Lehmann définit la limite située entre le manteau et le noyau, et marque un contraste important de densité entre les deux."}, {"id": "D", "text": "la discontinuité de Gutenberg définit la limite située entre noyau interne et noyau externe, et marque un contraste important de densité entre les deux."}]'::jsonb, ARRAY['A']::text[], 'Gutenberg (~2900 km) : limite manteau/noyau, fort contraste de densité ; Moho : croûte/manteau ; Lehmann : noyau externe/interne.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q103', 'exam_primary_2023_sciences_jan', 103, 'Astronomie — planètes (taille)', 'Selon leurs tailles on peut classer les planètes du système solaire dans l''ordre décroissant', false, '[{"id": "A", "text": "Saturne - Jupiter - Neptune - Uranus - Terre - Vénus - Mars - Mercure."}, {"id": "B", "text": "Saturne - Jupiter - Uranus - Neptune - Mars - Vénus - Terre - Mercure."}, {"id": "C", "text": "Jupiter - Saturne - Uranus - Neptune- Mars - Mercure - Terre - Vénus."}, {"id": "D", "text": "Jupiter - Saturne - Neptune - Uranus - Terre - Vénus - Mars - Mercure."}]'::jsonb, ARRAY['D']::text[], 'Par le diamètre, Uranus est légèrement plus grande que Neptune, donc aucune proposition n''est exacte ; D est la plus proche (et elle est correcte si on classe par la masse).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, 'إجابة مرجّحة حسب المصدر (manasseb) — للتحقق : بالقطر، أورانوس أكبر قليلًا من نبتون، فلا يوجد اقتراح صحيح تمامًا ؛ D هو الأقرب (وهو صحيح إذا رُتبت الكواكب حسب الكتلة).');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q104', 'exam_primary_2023_sciences_jan', 104, 'Astronomie — planètes (ordre)', 'Les noms des huit planètes dans l''ordre à partir du Soleil est :', false, '[{"id": "A", "text": "Mercure - Vénus - Terre - Mars - Jupiter - Saturne - Uranus - Neptune."}, {"id": "B", "text": "Vénus - Mercure - Terre - Mars - Jupiter - Saturne - Uranus - Neptune."}, {"id": "C", "text": "Mercure - Vénus - Terre - Mars - Jupiter - Saturne - Neptune - Uranus."}, {"id": "D", "text": "Vénus - Mercure - Terre - Mars - Saturne - Jupiter - Uranus - Neptune."}]'::jsonb, ARRAY['A']::text[], 'Mercure, Vénus, Terre, Mars, Jupiter, Saturne, Uranus, Neptune.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q105', 'exam_primary_2023_sciences_jan', 105, 'Astronomie — satellite naturel', 'On parle d''un satellite naturel lorsqu''il s''agit d'':', false, '[{"id": "A", "text": "un corps céleste massif et pratiquement sphérique en orbite autour d''une étoile."}, {"id": "B", "text": "une nuée ardente pratiquement sphérique en orbite autour d''une étoile."}, {"id": "C", "text": "un corps céleste massif et pratiquement sphérique en orbite autour d''une planète."}, {"id": "D", "text": "une nuée ardente pratiquement sphérique en orbite autour d''une planète."}]'::jsonb, ARRAY['C']::text[], 'Un satellite naturel orbite autour d''une planète.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q106', 'exam_primary_2023_sciences_jan', 106, 'Physique — états de la matière (solide)', 'Un solide non compact est caractérisé par les propriétés physiques suivantes :', false, '[{"id": "A", "text": "1 : il est constitué d''un seul bloc ; 2 : il n''a pas de forme propre ; 3 : il n''a pas de surface libre plane."}, {"id": "B", "text": "1 : il est constitué de grains ou fragments très petits ; 2 : il n''a pas de forme propre ; 3 : il n''a pas de surface libre plane."}, {"id": "C", "text": "1 : il est constitué de grains ou fragments très petits ; 2 : il a une forme propre ; 3 : il a une surface libre plane."}, {"id": "D", "text": "1 : il est constitué d''un seul bloc ; 2 : il a une forme propre ; 3 : il a une surface libre plane."}]'::jsonb, ARRAY['B']::text[], 'Solide divisé : grains, pas de forme propre, pas de surface libre plane (forme un tas).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q107', 'exam_primary_2023_sciences_jan', 107, 'Physique — états de la matière (liquide)', 'Un liquide, état de la matière, est doté des propriétés suivantes :', false, '[{"id": "A", "text": "1 - il occupe tout l''espace disponible ; 2 - il prend la forme du récipient qui le contient; 3 - il est compressible."}, {"id": "B", "text": "1- il est doté de la capacité d''écoulement, 2- il prend la forme du récipient qui le contient, 3- il a un volume propre."}, {"id": "C", "text": "1- il est doté de la capacité d''écoulement, 2- il prend la forme du récipient qui le contient, 3- il est compressible."}, {"id": "D", "text": "1 - il occupe tout l''espace disponible ; 2 - il prend la forme du récipient qui le contient; 3 - il est expansible."}]'::jsonb, ARRAY['B']::text[], 'Un liquide s''écoule, prend la forme du récipient et a un volume propre (incompressible).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q108', 'exam_primary_2023_sciences_jan', 108, 'Physique — température (conversion)', 'Le rapport de conversion des trois unités correspond à l''égalité suivant :', false, '[{"id": "A", "text": "T°C = (T°F − 32) × 5 ÷ 9 = T(K) - 273,15."}, {"id": "B", "text": "T°C = (T°F + 32) × 5 ÷ 9 = T(K) - 273,15."}, {"id": "C", "text": "T°C = (T°F + 32) × 5 ÷ 9 = T(K) + 273,15."}, {"id": "D", "text": "T°C = (T°F − 32) × 9 ÷ 5 = T(K) - 273,15."}]'::jsonb, ARRAY['A']::text[], 'θ(°C) = (θ(°F) − 32)×5/9 = T(K) − 273,15.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q109', 'exam_primary_2023_sciences_jan', 109, 'Physique — transfert thermique', 'Le régime stationnaire est :', false, '[{"id": "A", "text": "permanent et le champ de température est indépendant du temps."}, {"id": "B", "text": "variable et le champ de température évolue avec le temps."}, {"id": "C", "text": "permanent et le champ de température est dépendant du temps."}, {"id": "D", "text": "variable et le champ de température est indépendant du temps."}]'::jsonb, ARRAY['A']::text[], 'Régime stationnaire = permanent, champ de température indépendant du temps.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q110', 'exam_primary_2023_sciences_jan', 110, 'Physique — électricité (diode, Doc 6)', 'Dans les montages du document 6 : (figures 1 et 2 : générateur, lampe et diode)', false, '[{"id": "A", "text": "la lampe dans le circuit de la fig.1, s''éteint car la diode n''est pas passante : elle est branchée dans le sens du courant de + vers le - à l''extérieur du générateur."}, {"id": "B", "text": "la lampe dans le circuit de la fig.2, s''allume car la diode n''est pas passante : elle est branchée dans le sens du courant de - vers le + à l''extérieur du générateur."}, {"id": "C", "text": "la lampe dans le circuit de la fig.1, s''allume car la diode est passante : elle est branchée dans le sens du courant de + vers le - à l''extérieur du générateur."}, {"id": "D", "text": "la lampe dans le circuit de la fig.2, s''éteint car la diode est passante : elle est branchée dans le sens du courant de - vers le + à l''extérieur du générateur."}]'::jsonb, ARRAY['C']::text[], 'Une diode est passante quand elle est branchée dans le sens conventionnel du courant (de + vers − à l''extérieur du générateur) : la lampe s''allume. Les propositions A, B et D se contredisent elles-mêmes (lampe éteinte avec diode passante, ou l''inverse).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q111', 'exam_primary_2023_sciences_jan', 111, 'Physique — électricité (intensité)', 'L''intensité du courant électrique ( I ) qui traverse le climatiseur électrique est :', false, '[{"id": "A", "text": "I = U / P = 230 / 5000 = 0,046 A."}, {"id": "B", "text": "I = U + P = 230 + 5000 = 5230 A."}, {"id": "C", "text": "I = U x P = 230 x 5000 = 1150000 A."}, {"id": "D", "text": "I = P / U = 5000 / 230 = 21,73 A."}]'::jsonb, ARRAY['D']::text[], 'P = U·I ⇒ I = P/U = 5000/230 ≈ 21,7 A.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q112', 'exam_primary_2023_sciences_jan', 112, 'Physique — énergie électrique', 'Il faut environ 15 minutes pour faire baisser la température de la salle d''un degré Celsius. L''énergie (E) que ce climatiseur convertit en Joule (J) est :', false, '[{"id": "A", "text": "E = 5000 + (60 x 15) = 900 J."}, {"id": "B", "text": "E = 5000 x 60 = 300000 J."}, {"id": "C", "text": "E = 5000 x 15 = 75000 J."}, {"id": "D", "text": "E = 5000 x (60 x 15) = 4500000 J."}]'::jsonb, ARRAY['D']::text[], 'E = P·t = 5000 × 900 s = 4 500 000 J.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q113', 'exam_primary_2023_sciences_jan', 113, 'Physique — électricité (fusible)', 'Sous une tension de 230V ; l''intensité I que le fusible, branché pour sécuriser le climatiseur seul, doit supporter est :', false, '[{"id": "A", "text": "inférieure à 15 A."}, {"id": "B", "text": "inférieure à 21 A."}, {"id": "C", "text": "supérieure à 15 A."}, {"id": "D", "text": "supérieure à 21 A."}]'::jsonb, ARRAY['D']::text[], 'Le fusible doit supporter un courant supérieur au courant nominal (≈ 21,7 A).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q114', 'exam_primary_2023_sciences_jan', 114, 'Physique — magnétisme', 'Un aimant est un matériau dur, exerçant un champ magnétique, parmi ses propriétés :', false, '[{"id": "A", "text": "attirer le fer, le zinc, le nickel et le chrome."}, {"id": "B", "text": "le pôle Sud d''un aimant et le pôle Nord d''un autre se repoussent."}, {"id": "C", "text": "le pôle Nord d''un aimant et le pôle Nord d''un autre s''attirent."}, {"id": "D", "text": "attire le fer, le cobalt et le nickel."}]'::jsonb, ARRAY['D']::text[], 'Matériaux ferromagnétiques : fer, cobalt, nickel ; pôles opposés s''attirent, pôles de même nom se repoussent.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q115', 'exam_primary_2023_sciences_jan', 115, 'Physique — optique (chambre noire, Doc 7)', 'L''image A''B'' formée sur l''écran: (Document 7 : chambre noire — bougie AB, sténopé, écran ; image A''B'' renversée)', false, '[{"id": "A", "text": "diminue lorsque la distance entre la bougie et le sténopé (DO) diminue."}, {"id": "B", "text": "augmente lorsque la distance entre le sténopé et l''écran (OD'') augmente."}, {"id": "C", "text": "diminue lorsque la distance entre la bougie et le sténopé (DO) augmente."}, {"id": "D", "text": "augmente lorsque la distance entre la bougie et le sténopé (DO) augmente."}]'::jsonb, ARRAY['C']::text[], 'A''B''/AB = OD''/DO : à OD'' fixé, l''image diminue quand DO augmente.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, 'إجابة مرجّحة حسب المصدر (manasseb) — للتحقق : الاقتراح B صحيح أيضًا من الناحية العلمية (الصورة تكبر عندما تكبر OD′) ؛ C هو الجواب الأقرب لموضوع السؤال (تأثير المسافة DO).');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q116', 'exam_primary_2023_sciences_jan', 116, 'Physique — optique (chambre noire, Doc 7)', 'L''image A''B'' formée sur l''écran sera : (Document 7 : chambre noire — bougie AB, sténopé, écran)', false, '[{"id": "A", "text": "nette si l''ouverture du sténopé est de petite taille."}, {"id": "B", "text": "peu lumineuse si l''ouverture du sténopé est de grande taille"}, {"id": "C", "text": "floue si l''ouverture du sténopé est de petite taille."}, {"id": "D", "text": "nette si l''ouverture du sténopé est de grande taille."}]'::jsonb, ARRAY['A']::text[], 'Petite ouverture : image nette mais peu lumineuse ; grande ouverture : lumineuse mais floue.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q117', 'exam_primary_2023_sciences_jan', 117, 'Physique — optique (image réelle/virtuelle)', 'Une image est :', false, '[{"id": "A", "text": "réelle, lorsque les rayons lumineux divergent à travers un système optique."}, {"id": "B", "text": "virtuelle, lorsque les rayons lumineux se concentrent, ou convergent, sur un écran d''observation."}, {"id": "C", "text": "réelle, lorsque qu''elle est observée à travers un miroir ou une lentille."}, {"id": "D", "text": "réelle, lorsque les rayons lumineux se concentrent, ou convergent, sur un écran d''observation."}]'::jsonb, ARRAY['D']::text[], 'Image réelle : les rayons convergent effectivement et peuvent être recueillis sur un écran.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q118', 'exam_primary_2023_sciences_jan', 118, 'Physique — acoustique (éclair)', 'La distance qui nous sépare de l''éclair, dont on entend le bruit avec 5 secondes de retard, est :', false, '[{"id": "A", "text": "300000 x 5 = 1500 km."}, {"id": "B", "text": "330 x 5 = 1650 km."}, {"id": "C", "text": "330 x 5 = 1650 m."}, {"id": "D", "text": "300000 x 5 = 1500000 m."}]'::jsonb, ARRAY['C']::text[], 'd = v·t = 330 × 5 = 1650 m (vitesse du son ≈ 330 m/s).', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, 'Bord gauche de la p.42 coupé : l''ordre des options est de haut en bas A, B, C, D ; l''introduction (vitesse de la lumière 300 000 km/s) est partiellement coupée.');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q119', 'exam_primary_2023_sciences_jan', 119, 'Physique — acoustique (ultrasons)', 'La distance séparant une chauve-souris d''un insecte volant, dont elle reçoit la réflexion des ultrasons dans une durée de 1,2 seconde est :', false, '[{"id": "A", "text": "1,2 / 344 = 0,0034 m."}, {"id": "B", "text": "344 x 1,2/2 = 143,33 m."}, {"id": "C", "text": "344 x 2 = 688 m."}, {"id": "D", "text": "344 / 1,2 = 286,66 m."}]'::jsonb, ARRAY['B']::text[], 'Aller-retour : d = v × t / 2 = 344 × 1,2 / 2 = 206,4 m. B est la formule attendue ; le résultat imprimé dans le sujet (143,33 m) est faux, la bonne valeur est 206,4 m.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, 'La valeur imprimée dans l''option B (143,33 m) est arithmétiquement fausse : d = v×t/2 = 344×1,2/2 = 206,4 m. B reste la réponse adoptée (formule attendue d = v×t/2 et clé manasseb). La question porte sur une chauve-souris et des ultrasons (vitesse 344 m/s), et non sur un bateau/sondeur comme dans la première transcription.');
INSERT INTO public.questions (id, exam_id, number, category, text, is_multiple, options, correct_answers, explanation, question_type, source_type, source_url, verified, verification_note) VALUES
  ('exam_primary_2023_sciences_jan_q120', 'exam_primary_2023_sciences_jan', 120, 'Physique — acoustique (ultrasons)', 'Une onde ultrasonore est :', false, '[{"id": "A", "text": "une onde non audible de fréquence supérieure à 20 Hz."}, {"id": "B", "text": "une onde audible de fréquence inférieure à 20 Hz."}, {"id": "C", "text": "une onde non audible de fréquence supérieure à 20000 Hz."}, {"id": "D", "text": "une onde non audible de fréquence inférieure à 20000 Hz."}]'::jsonb, ARRAY['C']::text[], 'Ultrasons : fréquence supérieure à 20 000 Hz, non audibles.', 'qcm', 'third_party', 'https://www.manasseb.com/sujet/sujet-42526-enseignant-2023/', true, NULL);
